  function storyTargets(region){if(!S)return [];const targets=[],chapter=ch();if(chapter?.region===region)targets.push({id:chapter.id,type:'main',anchor:chapter.anchor,name:chapter.title,label:chapter.place,hero:null,chapter:true,done:false,color:'#f2d592'});for(const e of C.encounters.filter(e=>e.region===region))targets.push({id:e.id,type:'side',anchor:e.anchor||'side1',name:e.speaker||e.title,label:e.title,hero:e.hero&&e.hero!==S.hero?e.hero:null,done:S.progress.encounters.includes(e.id),color:e.kind==='battle'?'#e5a895':'#b8d6b3'});return targets;}
  function startWorld(){world=window.SevenWorld.create({container:$('#worldStage'),getState:()=>S,getPreviewHero:()=>chosenHero,isPaused:()=>battling||atlasOpen||!!modalType,canEnter:()=>true,getStoryTargets:storyTargets,getChapterHUD:chapterHud,getPlaceName:id=>ch()?.region===id?ch().place:null,getEquipment:()=>S?.sword,getLifeTargets:id=>life?.getTargets(id)||[],getCompanions:()=>life?.getCompanions()||[],onLifeInteract:id=>life?.open(id),onTower:showTower,getTowerStatus:()=>({unlocked:!!window.SevenTower?.unlocked(S),label:window.SevenTower?.unlocked(S)?'进入无尽试炼塔':'完成当前剑主八幕主线后开启'}),onTrackNext:()=>goChapter(false),onAtlas:openAtlas,onLocal:showLocal,onLocalMap:showLocalMap,onMain:()=>showChapter(),onSide:showEncounter,onLandmark:showLandmark,onDiscover:discover,onNotice:toast,onSave:save,onRegion:id=>{if(!S)return;S.current=id;selected=id;if(!S.visited.includes(id))S.visited.push(id);save();render();}});}
