  function validChapterAction(id){return !battling&&eventContext?.kind==='chapter'&&eventContext.id===id&&eventContext.hero===S?.hero&&eventContext.step===S.progress.step&&ch()?.id===id&&chapterAtHand(ch());}
  function finishChapter(id,choice){const result=R.complete(S,id,choice);if(!result)return;save();render();const a=result.chapter;openModal('chapter-outcome',`<div class="chapter-outcome"><span class="eyebrow">${result.ending?'传记终章 · 剑主归位':'这一幕，已写入江湖'}</span><h2 id="dialogTitle">${esc(a.title)}</h2><p class="story-copy">${esc(a.outcome)}</p><div class="sword-result">${itemArt(swordIcon(),{hero:S.hero})}<div><b>${esc(swordName())}</b><span>${esc(S.sword.technique)} · ${S.sword.hand==='left'?'左手':'右手'}持剑</span></div></div><div class="reward-grid">${[['xp','阅历'],['gold','铜钱'],['herbs','回春散']].filter(([k])=>a.reward[k]).map(([k,n])=>`<div class="reward-item"><b>+${a.reward[k]}</b>${n}</div>`).join('')}</div>${result.levels?`<div class="checkpoint-note">修为达到 Lv.${S.level} · 攻击 ${R.stats(S).attack.toFixed(1)} · 气血 ${Math.round(R.stats(S).hp)}</div>`:''}<section class="chapter-interlude"><span class="eyebrow">收剑之后 · 游历串场</span><p>${esc(C.life.interludes[a.id]||(result.ending?'七剑既已重聚，往后仍可结伴看山河、围坐叙旧。下一程往哪里走，由你决定。':'这一页已写入旅途。且听听身旁的动静——或在附近走走，或向茶客问问消息，或请一位相认的故人坐下说话。'))}</p></section><div class="chapter-actions"><button class="primary-button" data-action="close-modal">收剑，留在这一境</button><button class="secondary-button" data-action="life-rest-go" data-id="${S.current}">就近歇脚 · 茶饭与同行</button><button class="text-button" data-action="${result.ending?'roster':'go-chapter'}">${result.ending?'展开另一位剑主的传记':'看看下一幕 · '+esc(result.next.title)} ›</button><button class="text-button" data-action="bag">查看物品与佩剑</button></div></div>`);playNote(659,.22);}
  function collectBattleLoot(run,e,enemy){
    if(!S||run.kind==='tower'||activeBattle!==run||run.done||S.hero!==run.hero||run.preview||run.replay||e.training)return null;
    const drop=window.SevenLoot?.roll({kind:run.kind,lifeKind:S.life?.activeRun?.kind,preview:run.preview,replay:run.replay,training:!!e.training,dojo:!!e.dojo,enemy:{boss:!!enemy.boss,captain:!!enemy.captain,kind:enemy.kind}});
    const item=drop&&R.supply(drop.id);if(!item)return null;
    if(R.supplyCount(S,item.id)>=item.cap)return {...drop,name:item.name,quantity:0,overflow:true};
    const before={herbs:S.herbs,supplies:{...S.supplies}};
    if(item.id==='herb')S.herbs++;else S.supplies[item.id]=R.supplyCount(S,item.id)+1;
    if(!save()){Object.assign(S,before);R.record(S);return null;}
    run.loot=run.loot||{};run.loot[item.id]=(run.loot[item.id]||0)+1;
    return {...drop,name:item.name,quantity:1};
  }
