      if(run.loot){const lootText=Object.entries(run.loot).map(([id,n])=>R.supply(id).name+' ×'+n).join('、');R.log(S,'野外交锋 · 拾得补给',lootText+'；已即时入袋，撤退与败北不丢失。');toast('拾得补给：'+lootText);}
