    openModal('tower-result',header('无尽试炼塔',ongoing?'第 '+run.floor+' 层已破':result.retreated?'收剑出塔':'本次试炼结束',run.saveFailed?'本层奖励未能保存，本次登塔已安全结束。本层未发奖、未提升纪录；此前已保存奖励和真实药品消耗保留。':'已通关层数与奖励保留。')+`<div class="battle-summary">本次通关 ${run.cleared} 层 · 击破 ${run.kills} · 用时 ${Math.round(run.time)} 秒<br>个人最高 ${window.SevenTower.highest(S)} 层<br>本次已获 铜钱 ${run.gold} · 阅历 ${run.xp}${run.latestReward?'<br>本层奖励 铜钱 +'+run.latestReward.gold+' · 阅历 +'+run.latestReward.xp+(run.latestReward.item?'<br>首次突破赠礼 '+esc(R.growthItem(run.latestReward.item)?.name||'养成珍品')+' ×1，已收入行囊':''):''}</div><div class="modal-footer">${ongoing?'<button class="primary-button" data-action="tower-next">登上第 '+(run.floor+1)+' 层</button>':''}<button class="secondary-button" data-action="tower-exit">返回山河</button></div>`,{readOnly:true});
