  function showEncounter(id){const e=C.encounters.find(e=>e.id===id);if(!S||!e)return;if(!encounterAtHand(e)){goEncounter(id);return;}const done=S.progress.encounters.includes(id);openModal('encounter',header(e.kind==='battle'?'山间遭遇':'原作意象 · 顺路彩蛋',e.title,e.place||byLoc(e.region).name)+`<div class="encounter-card"><div class="event-icon">${itemArt(e.icon||'letter')}</div><p class="story-copy">${esc(done?e.outcome||e.text:e.intro||e.text)}</p>${(e.dialogue||[]).map(l=>`<div class="chapter-line"><b>${window.SevenUIArt?.speakerAvatar(l.speaker,S.hero,S.sword)||''}${esc(l.speaker)}</b><p>${esc(l.text)}</p></div>`).join('')}<details class="chapter-source"><summary>原作出处与选编说明</summary>${window.SevenDialogueAudit?.event(e.id)||''}${sourceLinks(e.sourceIds)}</details><p class="small-note">${esc(e.note||'原作意象彩蛋 · 本次游历就地完成')}</p>${!done&&e.kind==='battle'?life?.battlePreview({kind:'encounter',id},e.battle)||'':''}<div class="chapter-rewards">${done?'已留念 · 奖励已领取':esc(rewardText(e.reward))}</div><div class="chapter-actions">${done?'<button class="primary-button" data-action="close-modal">继续游历</button>':e.kind==='battle'?`<button class="secondary-button" data-action="close-modal">绕过此处</button><button class="primary-button" data-action="encounter-battle" data-id="${id}">拔剑解围</button>`:(e.choices?.length?e.choices:[{label:'驻足一刻，记下此事'}]).map((a,i)=>`<button class="choice-button" data-action="encounter-choice" data-id="${id}" data-index="${i}"><span class="choice-body"><strong>${esc(a.label)}</strong>${a.text?`<small>${esc(a.text)}</small>`:''}</span></button>`).join('')}</div></div>`);eventContext={kind:'encounter',id,hero:S.hero};}
  function goEncounter(id){const e=C.encounters.find(e=>e.id===id);if(!S||!e)return;closeModal();closeAtlas();world.flush();S.current=e.region;if(!S.visited.includes(S.current))S.visited.push(S.current);world.arrive(e.region,e.anchor||'side1',id);save();render();showEncounter(id);}
