    const restore=()=>{battling=false;layer.hidden=true;shell.inert=false;if(previousHidden===null)shell.removeAttribute('aria-hidden');else shell.setAttribute('aria-hidden',previousHidden);if(!S)showSelection();else if(returnFocus?.isConnected&&!returnFocus.closest('#modalLayer'))returnFocus.focus({preventScroll:true});else $('#worldStage canvas')?.focus({preventScroll:true});};
    try{window.SevenDojo.open({container:layer,heroId:id,stageId,onClose:restore});}
    catch(error){console.error(error);window.SevenDojo.instance?.destroy();window.SevenCombat.stop();layer.replaceChildren();restore();toast('演武场未能展开，请刷新后重试。');}
